Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -39,4 +39,32 @@
 <div id="overlay"><section class="dialog"><div class="fruit-orbit">🍓</div><div class="fruit-orbit two">🍋</div><div class="eyebrow" id="eyebrow">A FRESH ARCADE ADVENTURE</div><h1 id="title">FRUIT<br><span class="title-accent">FORCE</span></h1><p id="description" class="description">The orchard is under attack! Take to the skies, blast the bad fruit, and save the sweetest harvest.</p><div class="controls"><div class="keyhint"><b>WASD</b> / <b>←↑↓→</b> MOVE</div><div class="keyhint"><b>SPACE</b> FIRE</div><div class="keyhint"><b>P</b> PAUSE</div></div><button id="start" class="main-btn">START MISSION&nbsp; ↗</button><div class="dialog-foot">1 PLAYER · INFINITE HARVEST</div></section></div>
 <div id="touch-controls"><div id="stick"><div id="knob"></div></div><button id="fire">FIRE ✦</button></div>
 </main>
 <script>
+(()=>{
+const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d'),game=document.querySelector('#game');
+const $=s=>document.querySelector(s), ui={score:$('#score'),best:$('#best'),lives:$('#lives'),wave:$('#wave'),waveName:$('#wave-name'),power:$('#power'),powerNum:$('#power-num'),overlay:$('#overlay'),title:$('#title'),description:$('#description'),eyebrow:$('#eyebrow'),start:$('#start'),pause:$('#pause'),toast:$('#toast')};
+let W=0,H=0,dpr=1,last=0,clock=0,scroll=0,spawnTimer=0,shotTimer=0,flash=0,toastTimer=0;
+let state='ready',score=0,best=+(localStorage.getItem('fruitforce-best')||0),lives=3,power=0,wave=1,kills=0,keys={},touch={x:0,y:0,fire:false},player,bullets=[],foes=[],shots=[],particles=[],drops=[];
+const fruits=['🍎','🍋','🍓','🍇','🍐','🍊'],colors=['#fa5c79','#f9d456','#fa6983','#ae76ed','#96dd6a','#ff9e43'];
+ui.best.textContent=String(best).padStart(6,'0');
+function resize(){const r=game.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(player){player.x=Math.max(24,Math.min(W-24,player.x));player.y=Math.min(H-80,Math.max(90,player.y))}}
+new ResizeObserver(resize).observe(game);resize();
+function reset(){score=0;lives=3;power=0;wave=1;kills=0;clock=0;scroll=0;spawnTimer=.45;shotTimer=0;bullets=[];foes=[];shots=[];particles=[];drops=[];player={x:W/2,y:H*.78,r:17,invuln:1.6,tilt:0};updateHud()}
+function updateHud(){ui.score.textContent=String(score).padStart(6,'0');ui.best.textContent=String(best).padStart(6,'0');ui.lives.textContent='♥ '.repeat(Math.max(0,lives)).trim()||'—';ui.wave.textContent=String(wave).padStart(2,'0');ui.waveName.textContent=['· CITRUS SKY','· BERRY BLITZ','· PEAR PRESSURE','· MELON MAYHEM'][Math.min(3,Math.floor((wave-1)/2))];ui.power.style.width=power+'%';ui.powerNum.textContent=power+'%'}
+function startGame(){reset();state='playing';ui.overlay.classList.add('hidden');ui.pause.textContent='Ⅱ';last=performance.now()}
+function pauseGame(){if(state==='playing'){state='paused';showScreen('PAUSED','MISSION ON HOLD','Take a breath, pilot. The orchard can wait.','RESUME MISSION')}else if(state==='paused'){state='playing';ui.overlay.classList.add('hidden');last=performance.now()}}
+function showScreen(title,eyebrow,description,button){ui.title.innerHTML=title;ui.eyebrow.textContent=eyebrow;ui.description.textContent=description;ui.start.textContent=button+'  ↗';ui.overlay.classList.remove('hidden')}
+ui.start.addEventListener('click',()=>state==='paused'?pauseGame():startGame());ui.pause.addEventListener('click',pauseGame);
+addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='p'||k==='escape')pauseGame();if((k==='enter'||k===' ')&&(state==='ready'||state==='over'))startGame()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',()=>{keys={};if(state==='playing')pauseGame()});
+function setStick(e){const rect=$('#stick').getBoundingClientRect(),dx=e.clientX-(rect.left+rect.width/2),dy=e.clientY-(rect.top+rect.height/2),len=Math.hypot(dx,dy),max=rect.width*.34,n=len?Math.min(1,len/max):0;touch.x=len?dx/len*n:0;touch.y=len?dy/len*n:0;$('#knob').style.transform=`translate(calc(-50% + ${touch.x*max}px),calc(-50% + ${touch.y*max}px))`}
+const stick=$('#stick');stick.addEventListener('pointerdown',e=>{stick.setPointerCapture(e.pointerId);setStick(e)});stick.addEventListener('pointermove',e=>{if(e.buttons)setStick(e)});function releaseStick(){touch.x=touch.y=0;$('#knob').style.transform='translate(-50%,-50%)'}stick.addEventListener('pointerup',releaseStick);stick.addEventListener('pointercancel',releaseStick);const fire=$('#fire');fire.addEventListener('pointerdown',e=>{e.preventDefault();touch.fire=true;fire.setPointerCapture(e.pointerId)});fire.addEventListener('pointerup',()=>touch.fire=false);fire.addEventListener('pointercancel',()=>touch.fire=false);
+function rand(a,b){return a+Math.random()*(b-a)}
+function burst(x,y,color,n=12){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),v=rand(40,210);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.35,.8),max:.8,color,size:rand(2,5),spin:rand(-5,5)})}}
+function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.3}
+function spawnEnemy(){const isBig=Math.random()<Math.min(.22,.06+wave*.008),r=isBig?25:rand(16,21),type=Math.floor(Math.random()*fruits.length),x=rand(r+12,W-r-12),hp=isBig?3:1;foes.push({x,y:-r-10,r,hp,max:hp,type,baseX:x,phase:rand(0,Math.PI*2),speed:rand(78,125)+wave*5,fire:rand(1.5,3.8),big:isBig})}
+function shoot(){bullets.push({x:player.x-7,y:player.y-15,vy:-490,r:3.5});bullets.push({x:player.x+7,y:player.y-15,vy:-490,r:3.5});shotTimer=.2}
+function enemyFire(f){shots.push({x:f.x,y:f.y+f.r*.5,vx:(player.x-f.x)*.22,vy:rand(150,205)+wave*5,r:5,color:colors[f.type]})}
+function damage(){if(player.invuln>0)return;lives--;player.invuln=1.5;flash=.16;burst(player.x,player.y,'#83ecf0',18);updateHud();if(lives<=0)endGame()}
+function endGame(){state='over';best=Math.max(best,score);localStorage.setItem('fruitforce-best',best);updateHud();showScreen('HARVEST<br><span class="title-accent">OVER</span>','ORCHARD REPORT',`You scored ${String(score).padStart(6,'0')} points and saved ${kills} pieces of fruit. Ready for another run?`,'PLAY AGAIN')}
+function collectDrop(d){power=Math.min(100,power+25);score+=100;burst(d.x,d.y,'#c8f36a',14);updateHud();showToast(power===100?'JUICE BLAST READY!':'JUICE +25%')}
+function blast(){if(power<100)return;power=0;for(const f of [...foes]){score+=f.big?500:250;burst(f.x,f.y,colors[f.type],20)}foes=[];shots=[];updateHud();showToast('ORCHARD BLAST!')}

input.newString:
function blast(){if(power<100)return;power=0;for(const f of [...foes]){score+=f.big?500:250;burst(f.x,f.y,colors[f.type],20)}foes=[];shots=[];updateHud();showToast('ORCHARD BLAST!')}
function update(dt){if(state!=='playing')return;clock+=dt;scroll+=dt*75;flash=Math.max(0,flash-dt);if(toastTimer>0&&!(toastTimer-=dt>0))ui.toast.classList.remove('show');
 let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+touch.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+touch.y;const mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag}player.x=Math.max(25,Math.min(W-25,player.x+dx*290*dt));player.y=Math.max(82,Math.min(H-80,player.y+dy*290*dt));player.tilt+=(dx*.42-player.tilt)*Math.min(1,dt*7);player.invuln=Math.max(0,player.invuln-dt);
 if(keys[' ']||touch.fire){shotTimer-=dt;if(shotTimer<=0)shoot()}else shotTimer=Math.min(shotTimer,0);
 spawnTimer-=dt;if(spawnTimer<=0){spawnEnemy();spawnTimer=Math.max(.34,rand(1.05,1.55)-wave*.06)}
 for(const b of bullets)b.y+=b.vy*dt;bullets=bullets.filter(b=>b.y>-20);
 for(const f of foes){f.y+=f.speed*dt;f.x=f.baseX+Math.sin(clock*1.6+f.phase)*Math.min(55,W*.11);f.fire-=dt;if(f.fire<=0&&f.y>0&&f.y<H*.7){enemyFire(f);f.fire=rand(2,3.8)}}
 for(const s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt}shots=shots.filter(s=>s.y<H+20&&s.x>-20&&s.x<W+20);
 for(const d of drops)d.y+=d.vy*dt;drops=drops.filter(d=>d.y<H+20);
 for(let i=foes.length-1;i>=0;i--){const f=foes[i];if(f.y>H+30){foes.splice(i,1);continue}if(Math.hypot(f.x-player.x,f.y-player.y)<f.r+player.r*.7){foes.splice(i,1);damage();continue}for(let j=bullets.length-1;j>=0;j--){const b=bullets[j];if(Math.hypot(f.x-b.x,f.y-b.y)<f.r+b.r){bullets.splice(j,1);f.hp--;burst(b.x,b.y,'#fff2b0',3);if(f.hp<=0){foes.splice(i,1);score+=f.big?350:100;kills++;if(Math.random()<.14)drops.push({x:f.x,y:f.y,vy:85,r:10});burst(f.x,f.y,colors[f.type],f.big?22:14);if(kills%10===0){wave++;showToast('SECTOR '+String(wave).padStart(2,'0')+' — INCOMING!')}updateHud()}break}}}
 for(let i=shots.length-1;i>=0;i--){const s=shots[i];if(Math.hypot(s.x-player.x,s.y-player.y)<s.r+player.r*.65){shots.splice(i,1);damage()}}
 for(let i=drops.length-1;i>=0;i--){const d=drops[i];if(Math.hypot(d.x-player.x,d.y-player.y)<d.r+player.r+10){drops.splice(i,1);collectDrop(d)}}
 for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.12,dt);p.vy*=Math.pow(.12,dt);p.life-=dt}particles=particles.filter(p=>p.life>0);if(flash>0){} }
function drawBackground(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#171b46');g.addColorStop(.58,'#24244f');g.addColorStop(1,'#362451');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // distant orchard ridges
 for(let layer=0;layer<3;layer++){const y=H*(.43+layer*.14),amp=H*(.025+layer*.015),speed=.22+layer*.14;ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<=W+4;x+=8){let yy=y+Math.sin((x/W*5)+scroll*.006*speed+layer)*amp+Math.sin(x/W*11-scroll*.003)*amp*.3;ctx.lineTo(x,yy)}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=['#28264f','#30284e','#3d2c50'][layer];ctx.fill()}
 // stars
 for(let i=0;i<42;i++){let x=((i*197.3+Math.sin(i*12.7)*31)%W+W)%W,y=((i*83.7+scroll*(.12+(i%4)*.06))%H);let tw=.3+.7*Math.abs(Math.sin(clock*1.4+i));ctx.globalAlpha=tw*.65;ctx.fillStyle=i%5===0?'#b9f1f0':'#dce4ff';ctx.beginPath();ctx.arc(x,y,i%7===0?1.5:0.8,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
 // orchard canopy silhouettes
 for(let side=0;side<2;side++)for(let i=0;i<7;i++){const y=((i*145+scroll*.7)% (H+100))-50,x=side?W+18: -18;ctx.fillStyle=i%2?'#596052':'#62604f';ctx.globalAlpha=.55;ctx.beginPath();ctx.arc(x+(side?-1:1)*12,y,randRadius(i),0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
 // subtle playfield glow
 const glow=ctx.createRadialGradient(W/2,H*.44,0,W/2,H*.44,W*.58);glow.addColorStop(0,'#ffb6780b');glow.addColorStop(1,'#ffb67800');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H)}
function randRadius(i){return 12+(i%3)*5}
function drawFruit(f){const r=f.r,c=colors[f.type];ctx.save();ctx.translate(f.x,f.y);ctx.shadowColor=c;ctx.shadowBlur=f.big?18:9;const gr=ctx.createRadialGradient(-r*.34,-r*.4,2,0,0,r*1.2);gr.addColorStop(0,lighten(c));gr.addColorStop(.42,c);gr.addColorStop(1,darken(c));ctx.fillStyle=gr;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
 // leaf + stem
 ctx.strokeStyle='#533d43';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-r*.78);ctx.quadraticCurveTo(2,-r*1.2,5,-r*1.25);ctx.stroke();ctx.fillStyle='#b8e563';ctx.beginPath();ctx.ellipse(6,-r*.98,6,3,-.48,0,Math.PI*2);ctx.fill();
 // glossy highlight
 ctx.fillStyle='#ffffff3d';ctx.beginPath();ctx.ellipse(-r*.36,-r*.4,r*.2,r*.1,-.7,0,Math.PI*2);ctx.fill();
 // cheeky eyes
 ctx.fillStyle='#28213d';ctx.beginPath();ctx.ellipse(-r*.28,-r*.06,r*.11,r*.16,-.16,0,Math.PI*2);ctx.ellipse(r*.28,-r*.06,r*.11,r*.16,.16,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(-r*.3,-r*.11,r*.035,0,7);ctx.arc(r*.26,-r*.11,r*.035,0,7);ctx.fill();ctx.strokeStyle='#432338';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,r*.18,r*.16,.2,Math.PI-.2);ctx.stroke();if(f.big){ctx.strokeStyle='#fff0a3';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,r+4,-.9,.9);ctx.stroke()}ctx.restore()}
function lighten(hex){return hex+'aa'}function darken(hex){return hex+'cc'}

